#include <stdlib.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int edges = 2 * (N - 1);
    int *head = (int *)malloc((N + 1) * sizeof(int));
    int *to = (int *)malloc(edges * sizeof(int));
    int *next = (int *)malloc(edges * sizeof(int));

    for (int i = 0; i <= N; i++) head[i] = -1;

    int idx = 0;
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        to[idx] = b;
        next[idx] = head[a];
        head[a] = idx++;

        to[idx] = a;
        next[idx] = head[b];
        head[b] = idx++;
    }

    int *parent = (int *)calloc(N + 1, sizeof(int));
    int *order = (int *)malloc((N + 1) * sizeof(int));
    int *size = (int *)malloc((N + 1) * sizeof(int));

    for (int i = 1; i <= N; i++) size[i] = 1;

    int top = 0;
    order[top++] = 1;
    parent[1] = 0;

    for (int i = 0; i < top; i++) {
        int v = order[i];
        for (int e = head[v]; e != -1; e = next[e]) {
            int u = to[e];
            if (u == parent[v]) continue;
            parent[u] = v;
            order[top++] = u;
        }
    }

    int ans = N;

    for (int i = N - 1; i > 0; i--) {
        int v = order[i];
        int s = size[v];
        int diff = N - 2 * s;
        if (diff < 0) diff = -diff;
        if (diff < ans) ans = diff;
        size[parent[v]] += s;
    }

    printf("%d\n", ans);

    free(head);
    free(to);
    free(next);
    free(parent);
    free(order);
    free(size);

    return 0;
}
